head.b:skin:
/* ==========================================================================
   PROTHOM ALO STYLE BANGLADESH NEWS THEME — CORE STYLES
   ========================================================================== */
:root {
  --pa-red: #d32f2f;
  --pa-red-dark: #b71c1c;
  --pa-dark: #0f172a;
  --pa-text: #1e293b;
  --pa-muted: #64748b;
  --pa-bg: #f8fafc;
  --pa-card: #ffffff;
  --pa-border: #e2e8f0;
  --pa-hover: #0284c7;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
}

/* HIDE ALL DEFAULT BLOGGER GADGETS (Search, B Logo, Attribution, Archive, Profile, Report Abuse) */
#navbar, #navbar-iframe, .navbar,
#Attribution1, .Attribution, .widget.Attribution,
#ReportAbuse1, .ReportAbuse, .widget.ReportAbuse,
#Profile1, .Profile, .widget.Profile, .profile-link,
#BlogArchive1, .BlogArchive, .widget.BlogArchive,
#BlogSearch1, .BlogSearch, .widget.BlogSearch,
#Label1, .Label, .widget.Label,
.blog-feeds, .post-feeds, .feed-links,
.quickedit, .goog-inline-block, .widget-item-control {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  pointer-events: none !important;
  overflow: hidden !important;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Hind Siliguri', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--pa-bg);
  color: var(--pa-text);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; transition: color 0.15s ease; }
a:hover { color: var(--pa-red); }
.container { max-width: 1240px; margin: 0 auto; padding: 0 16px; }

/* 1. TOP UTILITY BAR */
.top-utility-bar {
  background: #ffffff;
  border-bottom: 1px solid var(--pa-border);
  font-size: 0.86rem;
  color: var(--pa-muted);
  padding: 6px 0;
}
.top-utility-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}
.top-date-meta {
  display: flex;
  gap: 12px;
  align-items: center;
  font-weight: 500;
}
.top-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.epaper-link {
  background: #f1f5f9;
  border: 1px solid var(--pa-border);
  padding: 3px 12px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  color: var(--pa-dark);
  font-size: 0.8rem;
  transition: all 0.2s ease;
}
.epaper-link:hover {
  background: var(--pa-red);
  color: #ffffff;
  border-color: var(--pa-red);
}

/* 2. BRAND HEADER */
.site-header {
  background: #ffffff;
  padding: 16px 0 14px;
  border-bottom: 1px solid var(--pa-border);
}
.site-header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
}
.brand-logo-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}
.brand-red-circle {
  width: 36px;
  height: 36px;
  background: var(--pa-red);
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-weight: 900;
  font-size: 1.25rem;
  box-shadow: 0 2px 6px rgba(211, 47, 47, 0.35);
}
.brand-title {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 2.3rem;
  font-weight: 800;
  color: var(--pa-red-dark);
  line-height: 1;
  letter-spacing: -0.5px;
}
.brand-tagline {
  font-size: 0.82rem;
  color: var(--pa-muted);
  font-weight: 500;
  margin-top: 4px;
  margin-left: 46px;
}
.header-search form {
  display: flex;
  align-items: center;
  background: #f8fafc;
  border: 1px solid var(--pa-border);
  border-radius: 24px;
  padding: 4px 14px;
  transition: border-color 0.2s ease;
}
.header-search form:focus-within { border-color: var(--pa-red); }
.header-search input {
  border: none;
  background: transparent;
  outline: none;
  font-family: inherit;
  font-size: 0.9rem;
  width: 170px;
}
.header-search button {
  border: none;
  background: transparent;
  cursor: pointer;
  font-size: 1rem;
  color: var(--pa-muted);
}

/* 3. MAIN NAVBAR (PROTHOM ALO STICKY TABS) */
.main-navbar {
  background: #ffffff;
  border-bottom: 3px solid var(--pa-red);
  position: sticky;
  top: 0;
  z-index: 99;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}
.nav-list {
  display: flex;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 4px;
}
.nav-list::-webkit-scrollbar { display: none; }
.nav-list li a {
  display: block;
  padding: 10px 14px;
  font-weight: 700;
  font-size: 0.98rem;
  white-space: nowrap;
  color: var(--pa-dark);
  border-bottom: 3px solid transparent;
  margin-bottom: -3px;
  transition: all 0.15s ease;
}
.nav-list li a:hover,
.nav-list li.active a {
  color: var(--pa-red);
  border-bottom-color: var(--pa-red);
}

/* 4. BREAKING NEWS TICKER */
.breaking-ticker {
  background: #ffffff;
  border-bottom: 1px solid var(--pa-border);
  margin-bottom: 22px;
}
.ticker-wrap {
  display: flex;
  align-items: center;
  overflow: hidden;
}
.ticker-badge {
  background: var(--pa-red);
  color: #ffffff;
  font-weight: 800;
  font-size: 0.85rem;
  padding: 8px 18px;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 6px;
  letter-spacing: 0.3px;
}
.ticker-marquee {
  padding: 8px 16px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 600;
  font-size: 0.94rem;
  color: var(--pa-dark);
}

/* 5. PROTHOM ALO SIGNATURE LEAD GRID (2fr 1.2fr 1fr) */
.prothomalo-lead-grid {
  display: grid;
  grid-template-columns: 2fr 1.25fr 1fr;
  gap: 22px;
  margin-bottom: 35px;
}
@media (max-width: 992px) {
  .prothomalo-lead-grid { grid-template-columns: 1fr; }
}

/* LEAD STORY (LEFT) */
.lead-story-card {
  background: #ffffff;
  border: 1px solid var(--pa-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
}
.lead-story-thumb {
  position: relative;
  aspect-ratio: 16 / 9;
  background: #0f172a;
  overflow: hidden;
}
.lead-story-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}
.lead-story-card:hover .lead-story-thumb img { transform: scale(1.03); }
.lead-story-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: var(--pa-red);
  color: #ffffff;
  font-weight: 800;
  font-size: 0.78rem;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  box-shadow: 0 2px 6px rgba(0,0,0,0.25);
}
.lead-story-body { padding: 22px; }
.lead-story-headline {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.7rem;
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: 12px;
  color: var(--pa-dark);
}
.lead-story-headline a { color: inherit; }
.lead-story-headline a:hover { color: var(--pa-red); }
.lead-story-snippet {
  font-size: 0.98rem;
  color: #475569;
  line-height: 1.65;
  margin-bottom: 16px;
}
.news-meta-row {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.82rem;
  color: var(--pa-muted);
  font-weight: 500;
}

/* SUB-LEAD COLUMN (MIDDLE) */
.sub-lead-column {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.sub-lead-card {
  background: #ffffff;
  border: 1px solid var(--pa-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  padding: 14px;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
}
.sub-lead-thumb {
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: 12px;
  background: #0f172a;
}
.sub-lead-thumb img { width: 100%; height: 100%; object-fit: cover; }
.sub-lead-title {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 6px;
}
.sub-lead-snippet {
  font-size: 0.88rem;
  color: var(--pa-muted);
  line-height: 1.5;
  margin-bottom: 8px;
}

/* RIGHT COLUMN: TABBED LATEST / MOST READ */
.tabbed-widget {
  background: #ffffff;
  border: 1px solid var(--pa-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  height: fit-content;
  box-shadow: var(--shadow-sm);
}
.tab-headers {
  display: flex;
  border-bottom: 2px solid var(--pa-border);
  background: #f8fafc;
}
.tab-btn {
  flex: 1;
  padding: 10px;
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--pa-muted);
  cursor: pointer;
}
.tab-btn.active {
  color: var(--pa-red);
  background: #ffffff;
  border-bottom: 2px solid var(--pa-red);
  margin-bottom: -2px;
}
.tab-list { list-style: none; padding: 12px 14px; }
.tab-item {
  display: flex;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--pa-border);
}
.tab-item:last-child { border-bottom: none; }
.tab-num {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--pa-red);
  line-height: 1;
  min-width: 24px;
}
.tab-item-title {
  font-size: 0.94rem;
  font-weight: 600;
  line-height: 1.4;
}
.tab-item-time {
  font-size: 0.76rem;
  color: #94a3b8;
  margin-top: 4px;
}

/* 6. CATEGORY SECTIONS (বিভাগীয় সংবাদ গ্রিড) */
.section-block {
  background: #ffffff;
  border: 1px solid var(--pa-border);
  border-radius: var(--radius-md);
  padding: 22px;
  margin-bottom: 30px;
  box-shadow: var(--shadow-sm);
}
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--pa-red);
  padding-bottom: 10px;
  margin-bottom: 20px;
}
.section-title {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--pa-dark);
  display: flex;
  align-items: center;
  gap: 8px;
}
.section-title-bar {
  width: 5px;
  height: 22px;
  background: var(--pa-red);
  border-radius: 3px;
  display: inline-block;
}
.section-more-btn {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--pa-red);
}
.section-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
@media (max-width: 900px) {
  .section-grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 550px) {
  .section-grid-4 { grid-template-columns: 1fr; }
}
.sec-card {
  display: flex;
  flex-direction: column;
}
.sec-card-thumb {
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: 10px;
  background: #0f172a;
}
.sec-card-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}
.sec-card:hover .sec-card-thumb img { transform: scale(1.04); }
.sec-card-title {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 6px;
}
.sec-card-time { font-size: 0.78rem; color: #94a3b8; }

/* 7. ALL POSTS NATIVE CARD GRID */
.native-posts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
  gap: 24px;
  margin-top: 18px;
}
.news-card {
  background: #ffffff;
  border: 1px solid var(--pa-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.news-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.news-card-thumb {
  aspect-ratio: 16 / 9;
  background: #0f172a;
  overflow: hidden;
}
.news-card-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}
.news-card:hover .news-card-thumb img { transform: scale(1.04); }
.news-card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.news-card-title {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 8px;
}
.news-card-snippet {
  font-size: 0.88rem;
  color: var(--pa-muted);
  line-height: 1.55;
  margin-bottom: 14px;
  flex-grow: 1;
}
.news-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: #94a3b8;
  border-top: 1px solid var(--pa-border);
  padding-top: 10px;
}

/* 8. SINGLE POST ARTICLE VIEW */
.single-article-wrap {
  background: #ffffff;
  border: 1px solid var(--pa-border);
  border-radius: var(--radius-md);
  padding: 30px;
  margin: 20px auto 40px;
  max-width: 860px;
  box-shadow: var(--shadow-sm);
}
.article-breadcrumb {
  font-size: 0.88rem;
  color: var(--pa-muted);
  margin-bottom: 16px;
  display: flex;
  gap: 8px;
  align-items: center;
}
.article-title {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 2.3rem;
  font-weight: 800;
  line-height: 1.35;
  color: var(--pa-dark);
  margin-bottom: 16px;
}
.article-meta-box {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 0;
  border-top: 1px solid var(--pa-border);
  border-bottom: 1px solid var(--pa-border);
  margin-bottom: 24px;
  font-size: 0.88rem;
  color: var(--pa-muted);
}
.article-lead-image {
  width: 100%;
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: 24px;
}
.article-lead-image img { width: 100%; height: auto; display: block; }
.article-body-content {
  font-size: 1.15rem;
  line-height: 1.85;
  color: #1e293b;
}
.article-body-content p { margin-bottom: 20px; }
.article-body-content img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius-sm);
  margin: 20px 0;
}
.article-body-content blockquote {
  border-left: 4px solid var(--pa-red);
  padding: 12px 20px;
  background: #f8fafc;
  font-family: 'Noto Serif Bengali', serif;
  font-size: 1.2rem;
  color: var(--pa-dark);
  margin: 24px 0;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

/* 9. SITE FOOTER */
.site-footer {
  background: #0f172a;
  color: #cbd5e1;
  padding: 45px 0 25px;
  margin-top: 50px;
  font-size: 0.92rem;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 35px;
  margin-bottom: 35px;
}
@media (max-width: 768px) {
  .footer-inner { grid-template-columns: 1fr; }
}
.footer-logo {
  font-family: 'Noto Serif Bengali', serif;
  font-size: 2rem;
  font-weight: 800;
  color: #ffffff;
  margin-bottom: 12px;
}
.footer-logo span { color: var(--pa-red); }
.footer-desc {
  font-size: 0.88rem;
  line-height: 1.65;
  color: #94a3b8;
  max-width: 440px;
}
.footer-links-title {
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 14px;
  font-size: 1.05rem;
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 9px; }
.footer-links a { color: #94a3b8; }
.footer-links a:hover { color: #ffffff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 22px;
  text-align: center;
  font-size: 0.84rem;
  color: #64748b;
}

div.script:
//
(function() {
  try {
    var days = ['রবিবার', 'সোমবার', 'মঙ্গলবার', 'বুধবার', 'বৃহস্পতিবার', 'শুক্রবার', 'শনিবার'];
    var months = ['জানুয়ারি', 'ফেব্রুয়ারি', 'মার্চ', 'এপ্রিল', 'মে', 'জুন', 'জুলাই', 'আগস্ট', 'সেপ্টেম্বর', 'অক্টোবর', 'নভেম্বর', 'ডিসেম্বর'];
    var toBn = function(n) {
      return String(n).replace(/[0-9]/g, function(d) { return '০১২৩৪৫৬৭৮৯'[d]; });
    };
    var now = new Date();
    var str = '📅 ' + days[now.getDay()] + ', ' + toBn(now.getDate()) + ' ' + months[now.getMonth()] + ' ' + toBn(now.getFullYear());
    var el = document.getElementById('live-bangla-date');
    if (el) el.textContent = str;
  } catch(e) {}
})();
//

body.script:
//
(function() {
  function extractThumb(entry) {
    if (entry.media$thumbnail && entry.media$thumbnail.url) {
      return entry.media$thumbnail.url.replace('/s72-c/', '/w1200-h675-p-k-no-nu/');
    }
    if (entry.content && entry.content.$t) {
      var m = entry.content.$t.match(/<img[^>]+src=["\']([^"\']+)["\']/i);
      if (m && m[1]) return m[1];
    }
    return 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=1000&auto=format&fit=crop&q=80';
  }

  function extractSnippet(entry) {
    var raw = (entry.summary && entry.summary.$t) ? entry.summary.$t : (entry.content ? entry.content.$t : '');
    var plain = raw.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    return plain.substring(0, 140) + '...';
  }

  function formatDate(isoStr) {
    var d = new Date(isoStr);
    var bnDigits = ['০','১','২','৩','৪','৫','৬','৭','৮','৯'];
    var months = ['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
    var day = String(d.getDate()).split('').map(function(c){ return bnDigits[c] || c; }).join('');
    var year = String(d.getFullYear()).split('').map(function(c){ return bnDigits[c] || c; }).join('');
    return day + ' ' + months[d.getMonth()] + ' ' + year;
  }

  // 1. POPULATE PROTHOM ALO SIGNATURE LEAD GRID (TOP 5 POSTS)
  var leadGridBox = document.getElementById('prothomalo-lead-grid');
  if (leadGridBox) {
    fetch('/feeds/posts/default?alt=json&max-results=8')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var entries = (data.feed && data.feed.entry) || [];
        if (entries.length === 0) return;

        // Update Ticker with top 3 titles
        var tickerEl = document.getElementById('ticker-news-text');
        if (tickerEl) {
          tickerEl.innerText = entries.slice(0, 4).map(function(e){ return e.title.$t; }).join(' • ');
        }

        // Column 1: Main Lead News
        var lead = entries[0];
        var leadLink = (lead.link.find(function(l) { return l.rel === 'alternate'; }) || {}).href || '#';
        var leadThumb = extractThumb(lead);
        var leadSnippet = extractSnippet(lead);
        var leadDate = formatDate(lead.published.$t);

        var leadHtml = '<article class="lead-story-card">' +
          '<a class="lead-story-thumb" href="' + leadLink + '">' +
            '<img src="' + leadThumb + '" alt="' + lead.title.$t.replace(/"/g, '&quot;') + '" loading="eager" />' +
            '<span class="lead-story-badge">🔥 শীর্ষ সংবাদ</span>' +
          '</a>' +
          '<div class="lead-story-body">' +
            '<h1 class="lead-story-headline"><a href="' + leadLink + '">' + lead.title.$t + '</a></h1>' +
            '<p class="lead-story-snippet">' + leadSnippet + '</p>' +
            '<div class="news-meta-row">' +
              '<span>✍️ নিজস্ব প্রতিবেদক</span> • <span>⏱️ ' + leadDate + '</span>' +
            '</div>' +
          '</div>' +
        '</article>';

        // Column 2: 2 Sub-Leads
        var subHtml = '<div class="sub-lead-column">';
        for (var i = 1; i < Math.min(entries.length, 3); i++) {
          var s = entries[i];
          var sLink = (s.link.find(function(l) { return l.rel === 'alternate'; }) || {}).href || '#';
          var sThumb = extractThumb(s);
          var sSnippet = extractSnippet(s);
          var sDate = formatDate(s.published.$t);
          subHtml += '<article class="sub-lead-card">' +
            '<a class="sub-lead-thumb" href="' + sLink + '">' +
              '<img src="' + sThumb + '" alt="' + s.title.$t.replace(/"/g, '&quot;') + '" loading="lazy" />' +
            '</a>' +
            '<h2 class="sub-lead-title"><a href="' + sLink + '">' + s.title.$t + '</a></h2>' +
            '<p class="sub-lead-snippet">' + sSnippet + '</p>' +
            '<div class="news-meta-row"><span>⏱️ ' + sDate + '</span></div>' +
          '</article>';
        }
        subHtml += '</div>';

        // Column 3: Tabbed List (Latest 5)
        var bnNums = ['১','২','৩','৪','৫'];
        var tabHtml = '<aside class="tabbed-widget">' +
          '<div class="tab-headers">' +
            '<button class="tab-btn active" type="button">সর্বশেষ</button>' +
            '<button class="tab-btn" type="button">সর্বাধিক পঠিত</button>' +
          '</div>' +
          '<ul class="tab-list">';
        for (var j = 0; j < Math.min(entries.length, 5); j++) {
          var t = entries[j];
          var tLink = (t.link.find(function(l) { return l.rel === 'alternate'; }) || {}).href || '#';
          var tDate = formatDate(t.published.$t);
          tabHtml += '<li class="tab-item">' +
            '<span class="tab-num">' + bnNums[j] + '</span>' +
            '<div>' +
              '<div class="tab-item-title"><a href="' + tLink + '">' + t.title.$t + '</a></div>' +
              '<div class="tab-item-time">' + tDate + '</div>' +
            '</div>' +
          '</li>';
        }
        tabHtml += '</ul></aside>';

        leadGridBox.innerHTML = leadHtml + subHtml + tabHtml;
      })
      .catch(function(e) {});
  }

  // 2. POPULATE THE 4 CATEGORY SECTIONS
  var categorySections = [
    { id: 'national', label: 'জাতীয়' },
    { id: 'sports', label: 'খেলা' },
    { id: 'economy', label: 'অর্থনীতি' },
    { id: 'tech', label: 'প্রযুক্তি' }
  ];

  categorySections.forEach(function(cat) {
    var gridEl = document.getElementById('grid-' + cat.id);
    if (!gridEl) return;

    var feedUrl = '/feeds/posts/default/-/' + encodeURIComponent(cat.label) + '?alt=json&max-results=4';
    fetch(feedUrl)
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var items = (data.feed && data.feed.entry) || [];
        if (items.length > 0) {
          gridEl.innerHTML = items.map(function(item) {
            var title = item.title.$t;
            var link = (item.link.find(function(l) { return l.rel === 'alternate'; }) || {}).href || '#';
            var thumb = extractThumb(item);
            var dateStr = formatDate(item.published.$t);
            return '<div class="sec-card">' +
              '<a class="sec-card-thumb" href="' + link + '"><img src="' + thumb + '" alt="' + title.replace(/"/g, '&quot;') + '" loading="lazy"/></a>' +
              '<h3 class="sec-card-title"><a href="' + link + '">' + title + '</a></h3>' +
              '<span class="sec-card-time">⏱️ ' + dateStr + '</span>' +
            '</div>';
          }).join('');
        }
      })
      .catch(function(e) {});
  });
})();
//
